static void DisplayMenu()
{
    Console.WriteLine("\n=== Adventure ===" );
    Console.WriteLine("1. Explore");
    Console.WriteLine("2. Rest");
    Console.WriteLine("3. Quit");
}

static string GetPlayerChoice()
{
    Console.Write("Choose: ");
    return Console.ReadLine() ?? "";
}

static int CalculateDamage(int baseDamage, bool critical)
{
    return critical ? baseDamage * 2 : baseDamage;
}

static void StartBattle(int playerHealth, int enemyHealth)
{
    Console.WriteLine("\n=== Battle ===" );
    Console.WriteLine($"Enemy HP: {enemyHealth}");
    Console.WriteLine($"Your HP: {playerHealth}");
    int damage = CalculateDamage(15, false);
    Console.WriteLine($"You deal {damage} damage!");
}

static bool IsGameOver(int playerHealth)
{
    return playerHealth <= 0;
}

// In Main:
int health = 100;
bool playing = true;
while (playing)
{
    DisplayMenu();
    string choice = GetPlayerChoice();
    if (choice == "1") StartBattle(health, 50);
    else if (choice == "3") playing = false;
}
Console.WriteLine("Thanks for playing!");
